(() => {
  'use strict';

  /* ===================== Configuração ===================== */
  const TILE = 64;               // tamanho de cada bloco do labirinto (o lobo desenhado tem 48x64)
  const K = TILE / 48;           // escala usada por tudo que foi desenhado para blocos de 48
  const VW = 800, VH = 512;      // resolução interna da tela
  const WOLF_SPEED = 140 * K, WOLF_SPRINT = 205 * K, WOLF_R = 14;
  const BASE_LIGHT = 160;        // raio da visão no início da fase
  const ORB_LIGHT = 20;          // quanto cada vaga-lume aumenta a visão (até o fim da fase)
  const MAX_ORB_LIGHT = 120;     // limite do bônus de visão
  const GRACE = 4;               // segundos antes do monstros acordarem
  const IMMORTAL_TIME = 8;       // duração do poder do livro
  const FAST_TIME = 7;           // duração do poder do raio
  const FAST_MUL = 1.5;          // multiplicador de velocidade do raio
  const MON_FOV = 100 * Math.PI / 180;   // abertura do cone de visão dos monstros
  const SAVE_KEY = 'labirinto-cepk-v1';
  const reduceMotion = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);

  const SPR = {
    up: 'data:image/png;base64,',
    down: 'data:image/png;base64,',
    left1: 'data:image/png;base64,',
    left2: 'data:image/png;base64,',
    right1: 'data:image/png;base64,',
    right2: 'data:image/png;base64,'
  };

  const $ = id => document.getElementById(id);
  const canvas = $('game');
  const ctx = canvas.getContext('2d');
  canvas.width = VW; canvas.height = VH;
  const darkCv = document.createElement('canvas');
  darkCv.width = VW; darkCv.height = VH;
  const dctx = darkCv.getContext('2d');

  const images = {};
  Object.keys(SPR).forEach(n => { const im = new Image(); im.src = SPR[n]; images[n] = im; });
  $('menuWolf').src = SPR.down;

  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  function mulberry32(a) {
    return function () {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  const fmtTime = s => {
    const m = Math.floor(s / 60), r = Math.floor(s % 60);
    return String(m).padStart(2, '0') + ':' + String(r).padStart(2, '0');
  };

  /* ===================== Recorde salvo ===================== */
  function loadSave() {
    try { return JSON.parse(localStorage.getItem(SAVE_KEY)) || {}; } catch (e) { return {}; }
  }
  function writeSave(data) {
    try { localStorage.setItem(SAVE_KEY, JSON.stringify(data)); } catch (e) { /* sem armazenamento */ }
  }

  /* ===================== Som ===================== */
  let actx = null, muted = false;
  function initAudio() {
    if (actx) return;
    try { actx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { actx = null; }
  }
  function tone(f, d, type, v, slide, delay) {
    if (!actx || muted) return;
    const t = actx.currentTime + (delay || 0);
    const o = actx.createOscillator(), g = actx.createGain();
    o.type = type || 'sine';
    o.frequency.setValueAtTime(f, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, f + slide), t + d);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(v || 0.15, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + d);
    o.connect(g); g.connect(actx.destination);
    o.start(t); o.stop(t + d + 0.03);
  }
  const sfx = {
    beat() { tone(55, 0.14, 'sine', 0.4, -15); tone(55, 0.14, 'sine', 0.3, -15, 0.17); },
    orb() { tone(660, 0.12, 'triangle', 0.15); tone(990, 0.18, 'triangle', 0.12, 0, 0.08); },
    caught() { tone(140, 0.7, 'sawtooth', 0.25, -110); tone(90, 0.8, 'square', 0.14, -60, 0.05); },
    win() { [523, 659, 784, 1047].forEach((f, i) => tone(f, 0.22, 'triangle', 0.15, 0, i * 0.11)); },
    wake() { tone(70, 0.9, 'sawtooth', 0.2, -25); },
    alert() { tone(540, 0.12, 'square', 0.12, -260); tone(380, 0.16, 'square', 0.1, -120, 0.1); },
    book() { [392, 523, 659, 784].forEach((f, i) => tone(f, 0.25, 'sine', 0.14, 0, i * 0.08)); },
    zap() { tone(900, 0.18, 'sawtooth', 0.12, -700); tone(1400, 0.1, 'square', 0.06, -900, 0.05); }
  };

  /* ===================== Estado ===================== */
  let MW = 0, MH = 0, grid = [];
  let floors = [];
  const G = {
    state: 'menu', level: 1, t: 0, msg: '', msgT: 0, hb: 0, danger: 0,
    wolf: null, monster: null, orbs: [], exit: null, seen: null, mazeCanvas: null,
    R: BASE_LIGHT, orbsTaken: 0, awake: false
  };
  const save = loadSave();

  /* ===================== Labirinto ===================== */
  function genMaze(cw, ch, rng) {
    const W = cw * 2 + 1, H = ch * 2 + 1;
    const g = Array.from({ length: H }, () => Array(W).fill(1));
    const vis = new Set(['0,0']);
    const stack = [[0, 0]];
    g[1][1] = 0;
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    while (stack.length) {
      const [cx, cy] = stack[stack.length - 1];
      const nb = [];
      for (const d of dirs) {
        const nx = cx + d[0], ny = cy + d[1];
        if (nx >= 0 && ny >= 0 && nx < cw && ny < ch && !vis.has(nx + ',' + ny)) nb.push([nx, ny, d]);
      }
      if (!nb.length) { stack.pop(); continue; }
      const [nx, ny, d] = nb[Math.floor(rng() * nb.length)];
      vis.add(nx + ',' + ny);
      g[cy * 2 + 1 + d[1]][cx * 2 + 1 + d[0]] = 0;
      g[ny * 2 + 1][nx * 2 + 1] = 0;
      stack.push([nx, ny]);
    }
    // abre algumas paredes para criar voltas (o monstro não consegue encurralar tão fácil)
    let carve = Math.floor(cw * ch * 0.12);
    for (let attempts = 0; carve > 0 && attempts < 4000; attempts++) {
      const x = 1 + Math.floor(rng() * (W - 2)), y = 1 + Math.floor(rng() * (H - 2));
      if (g[y][x] !== 1 || (x + y) % 2 !== 1) continue;
      const horiz = g[y][x - 1] === 0 && g[y][x + 1] === 0 && g[y - 1][x] === 1 && g[y + 1][x] === 1;
      const vert = g[y - 1][x] === 0 && g[y + 1][x] === 0 && g[y][x - 1] === 1 && g[y][x + 1] === 1;
      if (horiz || vert) { g[y][x] = 0; carve--; }
    }
    return g;
  }

  // mapa de distâncias (em blocos) a partir de um ponto
  function distMap(sx, sy) {
    const d = new Int16Array(MW * MH).fill(-1);
    const q = [sy * MW + sx];
    d[q[0]] = 0;
    for (let i = 0; i < q.length; i++) {
      const cur = q[i], cx = cur % MW, cy = (cur / MW) | 0;
      const nbs = [[cx + 1, cy], [cx - 1, cy], [cx, cy + 1], [cx, cy - 1]];
      for (const [nx, ny] of nbs) {
        if (nx < 0 || ny < 0 || nx >= MW || ny >= MH || grid[ny][nx] === 1) continue;
        const k = ny * MW + nx;
        if (d[k] !== -1) continue;
        d[k] = d[cur] + 1;
        q.push(k);
      }
    }
    return d;
  }

  function buildMazeCanvas(seed) {
    const cv = document.createElement('canvas');
    cv.width = MW * TILE; cv.height = MH * TILE;
    const c = cv.getContext('2d');
    c.scale(K, K);
    const rng = mulberry32(seed);
    const isWall = (x, y) => x < 0 || y < 0 || x >= MW || y >= MH || grid[y][x] === 1;
    { // o desenho abaixo usa blocos de 48 e é ampliado por K
      const TILE = 48;
      for (let y = 0; y < MH; y++) {
        for (let x = 0; x < MW; x++) {
          const px = x * TILE, py = y * TILE;
          if (isWall(x, y)) {
            const sh = Math.floor(rng() * 14);
            c.fillStyle = `rgb(${38 + sh},${44 + sh},${60 + sh})`;
            c.fillRect(px, py, TILE, TILE);
            for (let r = 0; r < 3; r++) {
              const y0 = py + r * 16;
              c.fillStyle = '#171c28';
              c.fillRect(px, y0 + 14, TILE, 2);
              const off = r % 2 ? 0 : 12;
              for (let k = 0; k < 3; k++) c.fillRect(px + off + k * 24, y0, 2, 14);
            }
            for (let i = 0; i < 5; i++) {
              c.fillStyle = rng() < 0.5 ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.12)';
              c.fillRect(px + Math.floor(rng() * 40), py + Math.floor(rng() * 40), 6 + Math.floor(rng() * 8), 4);
            }
            if (!isWall(x, y - 1)) { c.fillStyle = '#4a556f'; c.fillRect(px, py, TILE, 3); }
            if (!isWall(x, y + 1)) { c.fillStyle = '#0d1018'; c.fillRect(px, py + TILE - 5, TILE, 5); }
          } else {
            const sh = Math.floor(rng() * 8);
            c.fillStyle = `rgb(${22 + sh},${28 + sh},${39 + sh})`;
            c.fillRect(px, py, TILE, TILE);
            c.fillStyle = 'rgba(255,255,255,0.035)';
            if ((x + y) % 2 === 0) c.fillRect(px, py, TILE, TILE);
            for (let i = 0; i < 6; i++) {
              c.fillStyle = rng() < 0.6 ? 'rgba(0,0,0,0.18)' : 'rgba(255,255,255,0.05)';
              c.fillRect(px + Math.floor(rng() * 44), py + Math.floor(rng() * 44), 2 + Math.floor(rng() * 4), 2 + Math.floor(rng() * 3));
            }
            if (rng() < 0.18) {
              c.fillStyle = 'rgba(111,210,63,0.22)';
              const mx = px + Math.floor(rng() * 38), my = py + Math.floor(rng() * 38);
              c.fillRect(mx, my, 4, 2); c.fillRect(mx + 2, my - 2, 2, 2); c.fillRect(mx + 6, my + 2, 2, 2);
            }
            if (isWall(x, y - 1)) {
              const g = c.createLinearGradient(0, py, 0, py + 14);
              g.addColorStop(0, 'rgba(0,0,0,0.45)'); g.addColorStop(1, 'rgba(0,0,0,0)');
              c.fillStyle = g; c.fillRect(px, py, TILE, 14);
            }
          }
        }
      }
    }
    return cv;
  }

  /* ===================== Início de fase ===================== */
  function startLevel(level) {
    G.level = level;
    const cw = Math.min(7 + level * 2, 21), ch = Math.min(4 + level * 2, 15);
    const seed = (Math.random() * 4294967296) >>> 0;
    const rng = mulberry32(seed);
    grid = genMaze(cw, ch, rng);
    MH = grid.length; MW = grid[0].length;
    floors = [];
    for (let y = 0; y < MH; y++) for (let x = 0; x < MW; x++) if (grid[y][x] === 0) floors.push([x, y]);

    // o lobo começa num canto sorteado; a saída fica longe dele, então pode surgir em qualquer região
    const corners = [[1, 1], [MW - 2, 1], [1, MH - 2], [MW - 2, MH - 2]];
    const start = corners[Math.floor(rng() * 4)];
    G.start = { x: start[0], y: start[1] };
    const ds = distMap(start[0], start[1]);
    // a saída pode surgir em qualquer região: sorteia entre os cruzamentos mais distantes da largada
    let maxD = 0;
    for (let i = 0; i < ds.length; i++) if (ds[i] > maxD) maxD = ds[i];
    const minExit = Math.max(14, Math.floor(maxD * 0.6));
    let exitCands = floors.filter(([x, y]) => x % 2 === 1 && y % 2 === 1 && ds[y * MW + x] >= minExit);
    if (!exitCands.length) exitCands = [[MW - 2, MH - 2]];
    const [ex, ey] = exitCands[Math.floor(rng() * exitCands.length)];
    const exitD = ds[ey * MW + ex];
    G.exit = { x: ex, y: ey };

    // vaga-lumes
    G.orbs = [];
    const nOrbs = 3 + Math.floor(level / 2);
    let tries = 0;
    while (G.orbs.length < nOrbs && tries++ < 400) {
      const [x, y] = floors[Math.floor(rng() * floors.length)];
      const d = ds[y * MW + x];
      if (d < 8 || (x === ex && y === ey)) continue;
      if (G.orbs.some(o => Math.hypot(o.tx - x, o.ty - y) < 6)) continue;
      G.orbs.push({ tx: x, ty: y, x: x * TILE + TILE / 2, y: y * TILE + TILE / 2, ph: rng() * 6 });
    }

    // poderes: livro (imortal) e raio (velocidade)
    G.powers = [];
    const placePower = (kind, n) => {
      let placed = 0, tr = 0;
      while (placed < n && tr++ < 600) {
        const [x, y] = floors[Math.floor(rng() * floors.length)];
        if (ds[y * MW + x] < 6 || (x === ex && y === ey)) continue;
        if (G.orbs.some(o => o.tx === x && o.ty === y)) continue;
        if (G.powers.some(q => Math.hypot(q.tx - x, q.ty - y) < 5)) continue;
        G.powers.push({ kind, tx: x, ty: y, x: x * TILE + TILE / 2, y: y * TILE + TILE / 2, ph: rng() * 6 });
        placed++;
      }
    };
    placePower('book', level >= 5 ? 2 : 1);
    placePower('bolt', 1 + Math.floor(level / 3));

    // monstros: 1 até a fase 2, 2 a partir da 3, 3 a partir da 6
    const nMon = level >= 6 ? 3 : level >= 3 ? 2 : 1;
    const minD = Math.max(12, Math.floor(exitD * 0.5));
    let cands = floors.filter(([x, y]) => ds[y * MW + x] >= minD && !(x === ex && y === ey));
    if (!cands.length) cands = floors.filter(([x, y]) => ds[y * MW + x] > 8);
    G.monsters = [];
    for (let i = 0; i < nMon; i++) {
      let pool = cands.filter(([x, y]) => G.monsters.every(o => Math.hypot(o.tx - x, o.ty - y) >= 8));
      if (!pool.length) pool = cands;
      const [mx, my] = pool[Math.floor(rng() * pool.length)];
      G.monsters.push({
        x: mx * TILE + TILE / 2, y: my * TILE + TILE / 2, tx: mx, ty: my,
        mode: 'patrol', mem: 0, spot: 0, seeing: false, last: null, stun: 0,
        pmap: null, ptarget: null, anim: Math.random() * 3, fx: 1, fy: 0
      });
    }

    G.wolf = {
      x: (start[0] + 0.5) * TILE, y: (start[1] + 0.5) * TILE, dir: 'down', moving: false, anim: 0,
      stamina: 1, tired: false, imm: 0, fast: 0, vx: 0, vy: 1
    };
    G.seen = new Uint8Array(MW * MH);
    G.mazeCanvas = buildMazeCanvas(seed ^ 0x9e3779b9);
    G.t = 0; G.hb = 0; G.danger = 0; G.R = BASE_LIGHT; G.orbsTaken = 0; G.awake = false;
    G.orbsTotal = G.orbs.length;
    G.orbBonus = 0;
    // meta de tempo para a 3ª estrela: 6x o tempo de ir direto até a saída, mais uma folga
    G.par = Math.round(exitD * TILE / WOLF_SPEED * 6 + 15);
    setMsg('Ache a saída verde! Meta: ' + fmtTime(G.par), 4);
    updateHud(true);
  }

  function setMsg(text, secs) { G.msg = text; G.msgT = secs; }

  /* ===================== Entrada ===================== */
  const kb = {}, tp = {};
  const held = a => !!(kb[a] || tp[a]);
  const KEYMAP = {
    ArrowUp: 'up', KeyW: 'up', ArrowDown: 'down', KeyS: 'down',
    ArrowLeft: 'left', KeyA: 'left', ArrowRight: 'right', KeyD: 'right',
    ShiftLeft: 'sprint', ShiftRight: 'sprint', KeyE: 'sprint'
  };
  window.addEventListener('keydown', e => {
    const a = KEYMAP[e.code];
    if (a) { kb[a] = true; if (G.state === 'play') e.preventDefault(); return; }
    if (e.code === 'Space' && G.state === 'play') e.preventDefault();
    if (e.repeat) return;
    if (e.code === 'KeyP' || e.code === 'Escape') {
      if (G.state === 'play') pauseGame(); else if (G.state === 'pause') resumeGame();
    } else if (e.code === 'KeyM') {
      muted = !muted;
      setMsg(muted ? 'Som desligado' : 'Som ligado', 1.2);
    }
  });
  window.addEventListener('keyup', e => { const a = KEYMAP[e.code]; if (a) kb[a] = false; });
  window.addEventListener('blur', () => {
    for (const k in kb) kb[k] = false;
    for (const k in tp) tp[k] = false;
    document.querySelectorAll('.pad button.on').forEach(b => b.classList.remove('on'));
    if (G.state === 'play') pauseGame();
  });
  document.addEventListener('visibilitychange', () => { if (document.hidden && G.state === 'play') pauseGame(); });

  document.querySelectorAll('.pad button').forEach(b => {
    const a = b.dataset.act;
    const on = e => { e.preventDefault(); tp[a] = true; b.classList.add('on'); try { b.setPointerCapture(e.pointerId); } catch (x) { /* ok */ } };
    const off = e => { tp[a] = false; b.classList.remove('on'); };
    b.addEventListener('pointerdown', on);
    b.addEventListener('pointerup', off);
    b.addEventListener('pointercancel', off);
    b.addEventListener('lostpointercapture', off);
    b.addEventListener('contextmenu', e => e.preventDefault());
  });

  /* ===================== Telas (menu, pausa, fim) ===================== */
  const overlay = $('overlay'), ovTitle = $('ovTitle'), ovText = $('ovText'), ovStars = $('ovStars'), ovExtra = $('ovExtra');
  const ovBtn = $('ovBtn'), ovBtn2 = $('ovBtn2'), levelsBox = $('levels'), menuWolf = $('menuWolf');
  let onBtn = null, onBtn2 = null;
  const starStr = n => '★'.repeat(n) + '☆'.repeat(3 - n);
  const unlockedLevel = () => Math.max(1, save.maxLevel || 1);
  const totalStars = () => Object.values(save.stars || {}).reduce((a, b) => a + b, 0);

  function buildLevels() {
    while (levelsBox.firstChild) levelsBox.removeChild(levelsBox.firstChild);
    const un = unlockedLevel(), n = Math.max(12, un);
    for (let l = 1; l <= n; l++) {
      const s = (save.stars && save.stars[l]) || 0;
      const b = document.createElement('button');
      b.type = 'button'; b.className = 'lvl'; b.disabled = l > un;
      const num = document.createElement('b'); num.textContent = l;
      const st = document.createElement('span'); st.textContent = l > un ? '—' : starStr(s);
      b.appendChild(num); b.appendChild(st);
      b.setAttribute('aria-label', l > un ? `Fase ${l}, bloqueada` : `Fase ${l}, ${s} de 3 estrelas`);
      b.addEventListener('click', () => { initAudio(); beginPlay(l); });
      levelsBox.appendChild(b);
    }
  }

  function showOverlay(o) {
    ovTitle.textContent = o.title;
    ovText.textContent = o.text;
    ovStars.textContent = o.stars != null ? starStr(o.stars) : '';
    ovStars.hidden = o.stars == null;
    ovExtra.textContent = o.extra || '';
    ovExtra.hidden = !o.extra;
    ovBtn.textContent = o.btn; onBtn = o.onBtn;
    ovBtn2.hidden = !o.btn2;
    ovBtn2.textContent = o.btn2 || ''; onBtn2 = o.onBtn2 || null;
    menuWolf.hidden = !o.wolf;
    levelsBox.hidden = !o.levels;
    if (o.levels) buildLevels();
    overlay.hidden = false;
    try { ovBtn.focus({ preventScroll: true }); } catch (e) { /* ok */ }
  }
  function hideOverlay() { overlay.hidden = true; }
  ovBtn.addEventListener('click', () => { initAudio(); if (onBtn) onBtn(); });
  ovBtn2.addEventListener('click', () => { initAudio(); if (onBtn2) onBtn2(); });

  function showMenu() {
    G.state = 'menu';
    const un = unlockedLevel(), ts = totalStars();
    showOverlay({
      title: 'LABIRINTO CEPK',
      text: 'O lobo do CEPK ficou preso num labirinto sem luz, e tem algo caminhando lá dentro. Chegue ao portal verde antes que o monstro chegue em você. Cada fase vale até 3 estrelas.',
      extra: ts ? `Estrelas conquistadas: ${ts}` : '',
      levels: true, wolf: true,
      btn: `JOGAR FASE ${un}`, onBtn: () => beginPlay(un)
    });
  }
  function beginPlay(level) {
    startLevel(level);
    G.state = 'play';
    hideOverlay();
    last = performance.now();
  }
  function pauseGame() {
    if (G.state !== 'play') return;
    G.state = 'pause';
    showOverlay({
      title: 'PAUSADO', text: 'Respire. O monstro também espera.',
      btn: 'CONTINUAR', onBtn: resumeGame, btn2: 'SAIR PARA O MENU', onBtn2: showMenu
    });
  }
  function resumeGame() {
    if (G.state !== 'pause') return;
    G.state = 'play'; hideOverlay(); last = performance.now();
  }
  function winGame() {
    G.state = 'win';
    sfx.win();
    const allOrbs = G.orbsTaken >= G.orbsTotal;
    const fast = G.t <= G.par;
    const stars = 1 + (allOrbs ? 1 : 0) + (fast ? 1 : 0);
    save.times = save.times || {}; save.stars = save.stars || {};
    const best = save.times[G.level];
    const isBest = !best || G.t < best;
    if (isBest) save.times[G.level] = Math.round(G.t * 10) / 10;
    const prev = save.stars[G.level] || 0;
    save.stars[G.level] = Math.max(prev, stars);
    save.maxLevel = Math.max(save.maxLevel || 0, G.level + 1);
    writeSave(save);
    showOverlay({
      title: 'VOCÊ ESCAPOU!',
      text: `Fase ${G.level} em ${fmtTime(G.t)}${isBest && best ? ' (novo recorde!)' : ''}.`,
      stars,
      extra: `✓ Escapou do labirinto\n${allOrbs ? '✓' : '✗'} Todos os vaga-lumes (${G.orbsTaken}/${G.orbsTotal})\n${fast ? '✓' : '✗'} Dentro da meta de ${fmtTime(G.par)}`,
      btn: 'PRÓXIMA FASE', onBtn: () => beginPlay(G.level + 1), btn2: 'MENU', onBtn2: showMenu
    });
  }
  function loseGame() {
    G.state = 'lose';
    sfx.caught();
    showOverlay({
      title: 'O MONSTRO PEGOU VOCÊ',
      text: `Você durou ${fmtTime(G.t)} na fase ${G.level}. O labirinto foi embaralhado: a saída agora está em outro caminho.`,
      btn: 'TENTAR DE NOVO', onBtn: () => beginPlay(G.level), btn2: 'MENU', onBtn2: showMenu
    });
  }

  /* ===================== Colisão ===================== */
  function solidAt(px, py) {
    const tx = Math.floor(px / TILE), ty = Math.floor(py / TILE);
    if (tx < 0 || ty < 0 || tx >= MW || ty >= MH) return true;
    return grid[ty][tx] === 1;
  }
  function collides(x, y, r) {
    return solidAt(x - r, y - r) || solidAt(x + r, y - r) || solidAt(x - r, y + r) || solidAt(x + r, y + r);
  }

  function nudge(w, axis, amount) {
    const pos = axis === 'y' ? w.y : w.x;
    const off = (Math.floor(pos / TILE) + 0.5) * TILE - pos;
    if (Math.abs(off) > TILE * 0.4 || Math.abs(off) < 0.5) return;
    const step = clamp(off, -amount, amount);
    if (axis === 'y' ? !collides(w.x, w.y + step, WOLF_R) : !collides(w.x + step, w.y, WOLF_R)) {
      if (axis === 'y') w.y += step; else w.x += step;
    }
  }

  /* ===================== Monstros ===================== */
  // linha de visada: não atravessa paredes
  function losClear(x0, y0, x1, y1) {
    const n = Math.ceil(Math.hypot(x1 - x0, y1 - y0) / 10);
    for (let i = 1; i < n; i++) {
      const t = i / n;
      if (solidAt(x0 + (x1 - x0) * t, y0 + (y1 - y0) * t)) return false;
    }
    return true;
  }
  const monRange = () => (4.6 + Math.min(G.level - 1, 5) * 0.25) * TILE;

  // o monstro enxerga o lobo se ele está dentro do cone, perto o bastante e sem parede no meio
  function monSees(m, w) {
    const dx = w.x - m.x, dy = w.y - m.y, d = Math.hypot(dx, dy);
    if (d > monRange()) return false;
    if (d > TILE * 1.1) {
      const dot = (dx * m.fx + dy * m.fy) / d;
      if (dot < Math.cos(MON_FOV / 2)) return false;
    }
    return losClear(m.x, m.y, w.x, w.y);
  }

  function pickPatrolTarget(m) {
    const w = G.wolf;
    let target = null;
    if (Math.random() < 0.3) {
      const wm = distMap(Math.floor(w.x / TILE), Math.floor(w.y / TILE));
      const near = floors.filter(([x, y]) => { const d = wm[y * MW + x]; return d >= 4 && d <= 12; });
      if (near.length) target = near[Math.floor(Math.random() * near.length)];
    }
    if (!target) target = floors[Math.floor(Math.random() * floors.length)];
    m.ptarget = target;
    m.pmap = distMap(target[0], target[1]);
  }

  function monsterDecide(m) {
    const idx = m.ty * MW + m.tx;
    let map;
    if (m.mode === 'chase') {
      map = distMap(m.last[0], m.last[1]);
      // chegou onde viu o lobo pela última vez, ou perdeu o rastro: volta a patrulhar
      if (!m.seeing && (map[idx] === 0 || m.mem <= 0)) { m.mode = 'patrol'; m.pmap = null; }
    }
    if (m.mode !== 'chase') {
      if (!m.pmap || m.pmap[idx] === 0) pickPatrolTarget(m);
      map = m.pmap;
    }
    const here = map[idx];
    if (here <= 0) return;
    const nbs = [[m.tx + 1, m.ty], [m.tx - 1, m.ty], [m.tx, m.ty + 1], [m.tx, m.ty - 1]]
      .filter(([x, y]) => x >= 0 && y >= 0 && x < MW && y < MH && grid[y][x] === 0 && map[y * MW + x] === here - 1);
    if (nbs.length) {
      const [nx, ny] = nbs[Math.floor(Math.random() * nbs.length)];
      m.tx = nx; m.ty = ny;
    }
  }

  function updateMonster(m, dt) {
    if (!G.awake) return;
    if (m.stun > 0) { m.stun -= dt; m.anim += dt * 0.3; m.seeing = false; return; }
    const w = G.wolf;
    const d = Math.hypot(w.x - m.x, w.y - m.y);
    const sees = monSees(m, w);
    const hears = w.moving && w.sprinting && d < TILE * 3.5;   // correr faz barulho
    m.seeing = false;
    if (sees || hears) m.spot += dt / (m.mode === 'chase' ? 0.01 : d < TILE * 2.5 ? 0.25 : 0.5);
    else m.spot = Math.max(0, m.spot - dt / 1.5);
    if (m.spot >= 1 && (sees || hears)) {
      if (m.mode !== 'chase') sfx.alert();
      m.mode = 'chase'; m.seeing = true; m.spot = 1; m.mem = 3;
      m.last = [Math.floor(w.x / TILE), Math.floor(w.y / TILE)];
    } else if (m.mode === 'chase') m.mem -= dt;

    const chase = m.mode === 'chase';
    const speed = (chase ? Math.min(136, 112 + 7 * G.level) : 68 + 5 * G.level) * K;
    let budget = speed * dt;
    let guard = 0;
    let mvx = 0, mvy = 0;
    while (budget > 0 && guard++ < 4) {
      const cx = m.tx * TILE + TILE / 2, cy = m.ty * TILE + TILE / 2;
      const dx = cx - m.x, dy = cy - m.y, dd = Math.hypot(dx, dy);
      if (dd <= budget) {
        m.x = cx; m.y = cy; budget -= dd;
        const px = m.tx, py = m.ty;
        monsterDecide(m);
        if (m.tx === px && m.ty === py) break;
      } else {
        m.x += dx / dd * budget; m.y += dy / dd * budget; budget = 0;
        mvx = dx / dd; mvy = dy / dd;
      }
    }
    // o monstro olha para onde anda (o cone gira suavemente)
    if (mvx || mvy) {
      m.fx += (mvx - m.fx) * Math.min(1, dt * 9);
      m.fy += (mvy - m.fy) * Math.min(1, dt * 9);
      const l = Math.hypot(m.fx, m.fy) || 1; m.fx /= l; m.fy /= l;
    }
    m.anim += dt;
  }

  /* ===================== Atualização ===================== */
  function updateHud(force) {
    const w = G.wolf;
    $('hudLevel').textContent = G.level;
    $('hudTime').textContent = fmtTime(G.t);
    $('hudOrbs').textContent = G.orbsTaken + '/' + G.orbsTotal;
    $('hudPar').textContent = fmtTime(G.par);
    const fill = $('stamina');
    fill.style.transform = `scaleX(${clamp(w.stamina, 0, 1).toFixed(3)})`;
    fill.parentNode.classList.toggle('tired', w.tired);
  }

  function update(dt) {
    const w = G.wolf;
    G.t += dt;
    if (G.msgT > 0) G.msgT -= dt;
    w.imm = Math.max(0, w.imm - dt);
    w.fast = Math.max(0, w.fast - dt);

    let ix = (held('right') ? 1 : 0) - (held('left') ? 1 : 0);
    let iy = (held('down') ? 1 : 0) - (held('up') ? 1 : 0);
    const moving = ix !== 0 || iy !== 0;
    if (moving) { const l = Math.hypot(ix, iy); ix /= l; iy /= l; }

    const sprint = held('sprint') && moving && w.stamina > 0 && !w.tired;
    if (sprint) {
      w.stamina -= 0.4 * dt;
      if (w.stamina <= 0) { w.stamina = 0; w.tired = true; }
    } else {
      w.stamina = Math.min(1, w.stamina + (moving ? 0.18 : 0.3) * dt);
      if (w.tired && w.stamina > 0.3) w.tired = false;
    }
    w.sprinting = sprint;
    w.moving = moving;

    if (moving) {
      const sp = (sprint ? WOLF_SPRINT : WOLF_SPEED) * (w.fast > 0 ? FAST_MUL : 1);
      w.vx = ix; w.vy = iy;
      const nx = w.x + ix * sp * dt, ny = w.y + iy * sp * dt;
      // se bater numa quina, o lobo desliza para o centro do corredor em vez de travar
      if (!collides(nx, w.y, WOLF_R)) w.x = nx;
      else if (iy === 0) nudge(w, 'y', Math.abs(ix * sp * dt));
      if (!collides(w.x, ny, WOLF_R)) w.y = ny;
      else if (ix === 0) nudge(w, 'x', Math.abs(iy * sp * dt));
      w.dir = Math.abs(ix) >= Math.abs(iy) ? (ix > 0 ? 'right' : 'left') : (iy > 0 ? 'down' : 'up');
      w.anim += dt * (sprint ? 1.5 : 1) * (w.fast > 0 ? 1.4 : 1);
    }

    // visão: cada vaga-lume pego amplia o raio até o fim da fase
    const targetR = BASE_LIGHT + G.orbBonus;
    G.R += (targetR - G.R) * Math.min(1, dt * 5);

    // vaga-lumes
    for (let i = G.orbs.length - 1; i >= 0; i--) {
      const o = G.orbs[i];
      if (Math.hypot(o.x - w.x, o.y - w.y) < 34) {
        G.orbs.splice(i, 1);
        G.orbBonus = Math.min(MAX_ORB_LIGHT, G.orbBonus + ORB_LIGHT);
        G.orbsTaken++;
        sfx.orb();
        setMsg('Visão ampliada até o fim da fase!', 2);
      }
    }

    // poderes
    for (let i = G.powers.length - 1; i >= 0; i--) {
      const q = G.powers[i];
      if (Math.hypot(q.x - w.x, q.y - w.y) < 34) {
        G.powers.splice(i, 1);
        if (q.kind === 'book') { w.imm = IMMORTAL_TIME; sfx.book(); setMsg(`Livro mágico: imortal por ${IMMORTAL_TIME} s!`, 2.2); }
        else { w.fast = FAST_TIME; sfx.zap(); setMsg(`Raio: mais velocidade por ${FAST_TIME} s!`, 2.2); }
      }
    }

    // explorado (minimapa)
    const rr = G.R * 0.85;
    const x0 = Math.max(0, Math.floor((w.x - rr) / TILE)), x1 = Math.min(MW - 1, Math.floor((w.x + rr) / TILE));
    const y0 = Math.max(0, Math.floor((w.y - rr) / TILE)), y1 = Math.min(MH - 1, Math.floor((w.y + rr) / TILE));
    for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) {
      if (Math.hypot(x * TILE + TILE / 2 - w.x, y * TILE + TILE / 2 - w.y) < rr + 20) G.seen[y * MW + x] = 1;
    }

    if (!G.awake && G.t >= GRACE) {
      G.awake = true; sfx.wake();
      setMsg(G.monsters.length > 1 ? 'Algo acordou... mais de um!' : 'Algo acordou...', 2.4);
    }
    G.monsters.forEach(m => updateMonster(m, dt));

    // saída
    const ex = G.exit.x * TILE + TILE / 2, ey = G.exit.y * TILE + TILE / 2;
    if (Math.hypot(ex - w.x, ey - w.y) < 30) { updateHud(); winGame(); return; }

    // perigo e pegada (imortal: o monstro que encosta fica atordoado)
    let near = Infinity;
    for (const m of G.monsters) {
      if (!G.awake || m.stun > 0) continue;
      const dist = Math.hypot(m.x - w.x, m.y - w.y);
      near = Math.min(near, dist);
      if (dist < 34) {
        if (w.imm > 0) {
          m.stun = 2.5; m.mode = 'patrol'; m.pmap = null; m.spot = 0;
          sfx.zap(); setMsg('Monstro atordoado!', 1.4);
        } else { updateHud(); loseGame(); return; }
      }
    }
    G.danger = (G.awake && near < Infinity ? clamp(1 - near / (TILE * 7), 0, 1) : 0) * (w.imm > 0 ? 0.25 : 1);

    G.hb -= dt;
    if (G.danger > 0.12 && G.hb <= 0) { sfx.beat(); G.hb = 1.15 - 0.75 * G.danger; }

    updateHud();
  }

  /* ===================== Desenho ===================== */
  // monstro: 16x16 blocos, dois quadros de animação
  const MON_COL = { '#': '#20132e', 'o': '#3d2557', 'R': '#ff4040', 'W': '#f4efe6' };
  const MON_A = [
    '................',
    '......####......',
    '....########....',
    '...##########...',
    '..############..',
    '..##oo####oo##..',
    '.##RR######RR##.',
    '.##RR######RR##.',
    '.##############.',
    '.#W#W##WW##W#W#.',
    '.##############.',
    '..############..',
    '..#.##.##.##.#..',
    '.#..#..##..#..#.',
    '#...#......#...#',
    '................'
  ];
  const MON_B = MON_A.slice(0, 12).concat([
    '..##.#.##.#.##..',
    '.##..#....#..##.',
    '.#..#......#..#.',
    '................'
  ]);
  const MP = 4;

  function drawMonster(c, m) {
    const frame = Math.floor(m.anim * 4) % 2 ? MON_B : MON_A;
    const bob = Math.sin((G.t + 1) * 5) * 2;
    const ox = Math.round(m.x - 8 * MP), oy = Math.round(m.y - 9 * MP + bob);
    const gr = 60 * K;
    const g = c.createRadialGradient(m.x, m.y, 4, m.x, m.y, gr);
    g.addColorStop(0, 'rgba(255,40,40,0.28)'); g.addColorStop(1, 'rgba(255,40,40,0)');
    c.fillStyle = g; c.fillRect(m.x - gr, m.y - gr, gr * 2, gr * 2);
    c.fillStyle = 'rgba(0,0,0,0.4)';
    c.beginPath(); c.ellipse(m.x, m.y + 22 * K, 18 * K, 5 * K, 0, 0, Math.PI * 2); c.fill();
    for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) {
      const ch = frame[y][x];
      if (ch === '.') continue;
      c.fillStyle = MON_COL[ch];
      c.fillRect(ox + x * MP, oy + y * MP, MP, MP);
    }
    if (m.stun > 0) {
      c.fillStyle = '#ffe44d';
      for (let i = 0; i < 3; i++) {
        const a = G.t * 5 + i * 2.1;
        c.fillRect(Math.round(m.x + Math.cos(a) * 20 * K) - 3, Math.round(oy - 4 + Math.sin(a) * 5) - 3, 6, 6);
      }
    }
  }
  function drawMonsterEyes(c, m, alpha) {
    const bob = Math.sin((G.t + 1) * 5) * 2;
    const ox = m.x - 8 * MP, oy = m.y - 9 * MP + bob;
    c.globalAlpha = alpha;
    const eyeY = oy + 7 * MP, er = 34 * K;
    const gl = c.createRadialGradient(m.x, eyeY, 2, m.x, eyeY, er);
    gl.addColorStop(0, 'rgba(255,50,50,0.35)'); gl.addColorStop(1, 'rgba(255,50,50,0)');
    c.fillStyle = gl; c.fillRect(m.x - er, eyeY - er, er * 2, er * 2);
    c.fillStyle = '#ff3b3b';
    c.fillRect(ox + 3 * MP, oy + 6 * MP, 2 * MP, 2 * MP);
    c.fillRect(ox + 11 * MP, oy + 6 * MP, 2 * MP, 2 * MP);
    c.fillStyle = '#ffd7a8';
    c.fillRect(ox + 3 * MP, oy + 6 * MP, MP, MP);
    c.fillRect(ox + 11 * MP, oy + 6 * MP, MP, MP);
    c.globalAlpha = 1;
  }

  function drawWolf(c, w) {
    const step = Math.floor(w.anim * 5.5) % 2;
    const flip = (w.dir === 'up' || w.dir === 'down') && w.moving && step === 1;
    const name = (w.dir === 'up' || w.dir === 'down') ? w.dir : w.dir + (w.moving && step ? '2' : '1');
    const im = images[name];
    const DW = 48, DH = 64;
    const bob = w.moving ? -Math.abs(Math.sin(w.anim * 5.5 * Math.PI)) * 3 : Math.sin(G.t * 2) * 0.7;
    const sprite = (dx, dy, alpha) => {
      c.save();
      c.globalAlpha = alpha;
      c.translate(Math.round(w.x + dx), 0);
      if (flip) c.scale(-1, 1);
      if (im && im.complete) c.drawImage(im, -DW / 2, Math.round(w.y - 46 + bob + dy), DW, DH);
      c.restore();
    };
    c.fillStyle = 'rgba(0,0,0,0.4)';
    c.beginPath(); c.ellipse(w.x, w.y + 15, 14, 5, 0, 0, Math.PI * 2); c.fill();
    c.imageSmoothingEnabled = true;
    c.imageSmoothingQuality = 'high';

    // raio: rastro de imagens e brilho azul no chão
    if (w.fast > 0) {
      const g = c.createRadialGradient(w.x, w.y + 14, 2, w.x, w.y + 14, 34);
      g.addColorStop(0, 'rgba(110,224,255,0.55)'); g.addColorStop(1, 'rgba(110,224,255,0)');
      c.fillStyle = g; c.fillRect(w.x - 34, w.y - 20, 68, 68);
      if (w.moving) { sprite(-w.vx * 26, -w.vy * 26, 0.16); sprite(-w.vx * 13, -w.vy * 13, 0.3); }
    }
    // livro: aura dourada (pisca nos últimos 2 s)
    const blink = w.imm > 0 && w.imm < 2 && Math.floor(G.t * 8) % 2 === 0;
    if (w.imm > 0 && !blink) {
      const pr = 46 + Math.sin(G.t * 6) * 3;
      const g = c.createRadialGradient(w.x, w.y - 6, 8, w.x, w.y - 6, pr);
      g.addColorStop(0, 'rgba(255,224,110,0.05)'); g.addColorStop(0.7, 'rgba(255,214,90,0.32)'); g.addColorStop(1, 'rgba(255,214,90,0)');
      c.fillStyle = g; c.fillRect(w.x - pr, w.y - 6 - pr, pr * 2, pr * 2);
      c.strokeStyle = 'rgba(255,236,150,0.75)'; c.lineWidth = 2;
      c.beginPath(); c.ellipse(w.x, w.y - 6, 30, 38, 0, 0, Math.PI * 2); c.stroke();
    }
    sprite(0, 0, 1);
  }

  function drawExit(c, now) {
    const x = G.exit.x * TILE + TILE / 2, y = G.exit.y * TILE + TILE / 2;
    const p = 0.5 + 0.5 * Math.sin(now * 3);
    c.save();
    c.translate(x, y);
    c.scale(K, K);
    const g = c.createRadialGradient(0, 0, 2, 0, 0, 44);
    g.addColorStop(0, 'rgba(160,255,120,0.9)'); g.addColorStop(0.5, 'rgba(90,210,60,0.45)'); g.addColorStop(1, 'rgba(90,210,60,0)');
    c.fillStyle = g; c.fillRect(-46, -46, 92, 92);
    c.lineWidth = 4;
    for (let i = 0; i < 3; i++) {
      c.strokeStyle = i === 1 ? '#ffffff' : '#6fd23f';
      c.globalAlpha = 0.9 - i * 0.2;
      c.beginPath();
      c.ellipse(0, 0, 14 + i * 5 + p * 2, 20 + i * 5 + p * 2, 0, now * (i % 2 ? -1 : 1) * 2, now * (i % 2 ? -1 : 1) * 2 + Math.PI * 1.5);
      c.stroke();
    }
    c.globalAlpha = 1;
    c.restore();
  }

  function drawOrb(c, o, now) {
    const f = 0.6 + 0.4 * Math.sin(now * 4 + o.ph);
    const bx = o.x + Math.sin(now * 1.3 + o.ph) * 5, by = o.y + Math.cos(now * 1.7 + o.ph) * 4;
    const gr = 26 * K;
    const g = c.createRadialGradient(bx, by, 1, bx, by, gr);
    g.addColorStop(0, `rgba(227,255,138,${0.85 * f})`); g.addColorStop(1, 'rgba(227,255,138,0)');
    c.fillStyle = g; c.fillRect(bx - gr, by - gr, gr * 2, gr * 2);
    c.fillStyle = '#f7ffc4';
    c.fillRect(Math.round(bx) - 3, Math.round(by) - 3, 6, 6);
  }

  // livro aberto: capa roxa, páginas creme e lombada dourada
  function drawBook(c, x, y, sc) {
    c.save(); c.translate(x, y); c.scale(sc, sc);
    c.fillStyle = '#4b2a86';
    c.beginPath(); c.moveTo(-16, -7); c.lineTo(0, -4); c.lineTo(16, -7); c.lineTo(16, 11); c.lineTo(0, 14); c.lineTo(-16, 11); c.closePath(); c.fill();
    c.fillStyle = '#f6ecd2';
    c.beginPath(); c.moveTo(-14, -9); c.lineTo(0, -6); c.lineTo(0, 10); c.lineTo(-14, 7); c.closePath(); c.fill();
    c.fillStyle = '#e4d5ae';
    c.beginPath(); c.moveTo(14, -9); c.lineTo(0, -6); c.lineTo(0, 10); c.lineTo(14, 7); c.closePath(); c.fill();
    c.strokeStyle = '#a08c62'; c.lineWidth = 1;
    for (let i = 0; i < 4; i++) {
      c.beginPath(); c.moveTo(-11, -5 + i * 3.6); c.lineTo(-3, -3.5 + i * 3.6); c.stroke();
      c.beginPath(); c.moveTo(3, -3.5 + i * 3.6); c.lineTo(11, -5 + i * 3.6); c.stroke();
    }
    c.strokeStyle = '#ffd45a'; c.lineWidth = 1.8;
    c.beginPath(); c.moveTo(0, -6); c.lineTo(0, 11); c.stroke();
    c.restore();
  }
  // raio amarelo
  function drawBolt(c, x, y, sc) {
    c.save(); c.translate(x, y); c.scale(sc, sc);
    c.beginPath();
    c.moveTo(3, -15); c.lineTo(-9, 2); c.lineTo(-1, 2); c.lineTo(-4, 15); c.lineTo(10, -4); c.lineTo(2, -4); c.lineTo(7, -15);
    c.closePath();
    c.fillStyle = '#ffe44d'; c.fill();
    c.lineWidth = 1.6; c.strokeStyle = '#fff6b8'; c.lineJoin = 'round'; c.stroke();
    c.restore();
  }
  function drawPower(c, q, now) {
    const bx = q.x, by = q.y + Math.sin(now * 2.4 + q.ph) * 4;
    const col = q.kind === 'book' ? '190,130,255' : '110,224,255';
    const gr = 34 * K, f = 0.65 + 0.35 * Math.sin(now * 4 + q.ph);
    const g = c.createRadialGradient(bx, by, 2, bx, by, gr);
    g.addColorStop(0, `rgba(${col},${0.7 * f})`); g.addColorStop(1, `rgba(${col},0)`);
    c.fillStyle = g; c.fillRect(bx - gr, by - gr, gr * 2, gr * 2);
    c.fillStyle = 'rgba(0,0,0,0.35)';
    c.beginPath(); c.ellipse(bx, q.y + 18, 12, 4, 0, 0, Math.PI * 2); c.fill();
    if (q.kind === 'book') drawBook(c, bx, by, 1.15); else drawBolt(c, bx, by, 1.1);
  }

  // cone de visão do monstro (parado nas paredes: usa a mesma linha de visada da detecção)
  function drawVision(c, m, alpha) {
    const range = monRange(), a0 = Math.atan2(m.fy, m.fx), half = MON_FOV / 2;
    c.beginPath(); c.moveTo(m.x, m.y);
    for (let i = 0; i <= 20; i++) {
      const a = a0 - half + MON_FOV * i / 20, cs = Math.cos(a), sn = Math.sin(a);
      let r = 0;
      while (r < range && !solidAt(m.x + cs * (r + 10), m.y + sn * (r + 10))) r += 10;
      c.lineTo(m.x + cs * r, m.y + sn * r);
    }
    c.closePath();
    const col = m.mode === 'chase' ? '255,50,50' : m.spot > 0.05 ? '255,120,50' : '255,190,70';
    const g = c.createRadialGradient(m.x, m.y, 8, m.x, m.y, range);
    g.addColorStop(0, `rgba(${col},${(0.36 * alpha).toFixed(3)})`); g.addColorStop(1, `rgba(${col},0)`);
    c.fillStyle = g; c.fill();
  }

  function drawPowerHud(c) {
    const w = G.wolf;
    let y = 30;
    [['book', w.imm, IMMORTAL_TIME, '#ffd45a'], ['bolt', w.fast, FAST_TIME, '#6fe0ff']].forEach(([k, t, max, col]) => {
      if (t <= 0) return;
      c.fillStyle = 'rgba(4,7,12,0.78)'; c.fillRect(10, y - 20, 132, 34);
      c.strokeStyle = '#232f43'; c.lineWidth = 2; c.strokeRect(10, y - 20, 132, 34);
      if (k === 'book') drawBook(c, 30, y - 2, 0.85); else drawBolt(c, 30, y - 2, 0.75);
      c.fillStyle = '#232f43'; c.fillRect(52, y - 2, 80, 8);
      c.fillStyle = col; c.fillRect(52, y - 2, 80 * clamp(t / max, 0, 1), 8);
      c.font = '9px "Press Start 2P", "Courier New", monospace';
      c.fillStyle = '#e8f0e4'; c.fillText(Math.ceil(t) + ' s', 52, y - 8);
      y += 40;
    });
  }

  function punch(sx, sy, r, inner, a) {
    const g = dctx.createRadialGradient(sx, sy, r * inner, sx, sy, r);
    g.addColorStop(0, `rgba(0,0,0,${a})`); g.addColorStop(1, 'rgba(0,0,0,0)');
    dctx.fillStyle = g;
    dctx.beginPath(); dctx.arc(sx, sy, r, 0, Math.PI * 2); dctx.fill();
  }

  function drawMinimap(c) {
    const cs = Math.max(3, Math.min(6, Math.floor(170 / MW), Math.floor(110 / MH)));
    const mw = MW * cs, mh = MH * cs, ox = VW - mw - 14, oy = 14;
    c.fillStyle = 'rgba(4,7,12,0.78)'; c.fillRect(ox - 4, oy - 4, mw + 8, mh + 8);
    c.strokeStyle = '#232f43'; c.lineWidth = 2; c.strokeRect(ox - 4, oy - 4, mw + 8, mh + 8);
    for (let y = 0; y < MH; y++) for (let x = 0; x < MW; x++) {
      if (!G.seen[y * MW + x]) continue;
      c.fillStyle = grid[y][x] === 1 ? '#18202f' : '#4b5f7d';
      c.fillRect(ox + x * cs, oy + y * cs, cs, cs);
    }
    if (G.seen[G.exit.y * MW + G.exit.x]) {
      c.fillStyle = '#6fd23f'; c.fillRect(ox + G.exit.x * cs - 1, oy + G.exit.y * cs - 1, cs + 2, cs + 2);
    }
    const w = G.wolf;
    if (Math.floor(G.t * 3) % 2 === 0 || G.state !== 'play') {
      c.fillStyle = '#e3ff8a';
      c.fillRect(ox + (w.x / TILE) * cs - 2, oy + (w.y / TILE) * cs - 2, 4, 4);
    }
    c.fillStyle = '#ff4040';
    G.monsters.forEach(m => {
      if (Math.hypot(m.x - w.x, m.y - w.y) < G.R) c.fillRect(ox + (m.x / TILE) * cs - 2, oy + (m.y / TILE) * cs - 2, 4, 4);
    });
  }

  function render() {
    const w = G.wolf;
    const now = performance.now() / 1000;
    const camX = Math.round(clamp(w.x - VW / 2, 0, Math.max(0, MW * TILE - VW)));
    const camY = Math.round(clamp(w.y - VH / 2, 0, Math.max(0, MH * TILE - VH)));

    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.fillStyle = '#000'; ctx.fillRect(0, 0, VW, VH);
    ctx.drawImage(G.mazeCanvas, camX, camY, VW, VH, 0, 0, VW, VH);

    ctx.save();
    ctx.translate(-camX, -camY);
    drawExit(ctx, now);
    G.orbs.forEach(o => drawOrb(ctx, o, now));
    G.powers.forEach(q => drawPower(ctx, q, now));
    // quem está mais abaixo na tela é desenhado por cima
    const actors = G.monsters.map(m => ({ y: m.y, draw: () => drawMonster(ctx, m) }));
    actors.push({ y: w.y, draw: () => drawWolf(ctx, w) });
    actors.sort((p, q) => p.y - q.y).forEach(a => a.draw());
    ctx.restore();

    // escuridão com um círculo de luz em volta do lobo
    const flick = reduceMotion ? 0 : Math.sin(now * 9) * 2.5 + Math.sin(now * 23) * 1.5;
    const R = G.R + flick;
    const sx = w.x - camX, sy = w.y - camY;
    dctx.globalCompositeOperation = 'source-over';
    dctx.clearRect(0, 0, VW, VH);
    dctx.fillStyle = 'rgba(1,3,8,0.985)';
    dctx.fillRect(0, 0, VW, VH);
    dctx.globalCompositeOperation = 'destination-out';
    punch(sx, sy, R, 0.4, 1);
    punch(G.exit.x * TILE + TILE / 2 - camX, G.exit.y * TILE + TILE / 2 - camY, 78 * K, 0.1, 0.55);
    G.orbs.forEach(o => punch(o.x - camX, o.y - camY, 40 * K, 0.1, 0.5));
    G.powers.forEach(q => punch(q.x - camX, q.y - camY, 46 * K, 0.1, 0.6));
    dctx.globalCompositeOperation = 'source-over';
    ctx.drawImage(darkCv, 0, 0);

    // olhos, cone de visão e alerta dos monstros, visíveis um pouco além da luz
    if (G.awake || G.state === 'menu') {
      ctx.save(); ctx.translate(-camX, -camY);
      G.monsters.forEach(m => {
        const d = Math.hypot(m.x - w.x, m.y - w.y);
        if (G.awake && m.stun <= 0 && d < R * 2.1) drawVision(ctx, m, clamp(1.15 - d / (R * 2.1), 0, 1));
        if (d > R * 0.7 && d < R * 1.55) {
          const a = clamp(1 - (d - R) / (R * 0.55), 0, 1) * 0.95;
          drawMonsterEyes(ctx, m, Math.max(a, 0.0));
        }
        if (G.awake && m.stun <= 0 && d < R * 1.55 && (m.mode === 'chase' || m.spot > 0.05)) {
          ctx.font = '16px "Press Start 2P", "Courier New", monospace';
          ctx.textAlign = 'center';
          ctx.fillStyle = m.mode === 'chase' ? '#ff4040' : '#ffb347';
          ctx.fillText(m.mode === 'chase' ? '!' : '?', m.x, m.y - 44 * K);
          ctx.textAlign = 'left';
        }
      });
      ctx.restore();
    }

    // borda vermelha quando o monstro está perto
    if (G.danger > 0.05) {
      const pulse = reduceMotion ? 1 : 0.75 + 0.25 * Math.sin(now * (4 + G.danger * 8));
      const g = ctx.createRadialGradient(VW / 2, VH / 2, VH * 0.3, VW / 2, VH / 2, VW * 0.62);
      g.addColorStop(0, 'rgba(255,0,0,0)');
      g.addColorStop(1, `rgba(255,20,20,${(0.5 * G.danger * pulse).toFixed(3)})`);
      ctx.fillStyle = g; ctx.fillRect(0, 0, VW, VH);
    }

    drawMinimap(ctx);
    drawPowerHud(ctx);

    if (G.msgT > 0 && G.state === 'play') {
      ctx.globalAlpha = clamp(G.msgT, 0, 1);
      ctx.font = '13px "Press Start 2P", "Courier New", monospace';
      ctx.textAlign = 'center';
      ctx.fillStyle = '#000'; ctx.fillText(G.msg, VW / 2 + 2, VH - 28 + 2);
      ctx.fillStyle = '#e3ff8a'; ctx.fillText(G.msg, VW / 2, VH - 28);
      ctx.globalAlpha = 1; ctx.textAlign = 'left';
    }
  }

  /* ===================== Laço principal ===================== */
  let last = 0;
  function frame(ts) {
    const dt = Math.min(0.05, (ts - last) / 1000 || 0);
    last = ts;
    if (G.state === 'play') update(dt);
    render();
    requestAnimationFrame(frame);
  }

  startLevel(1);
  G.state = 'menu';
  showMenu();
  requestAnimationFrame(frame);

  if (window.__LOBO_TEST) window.__LOBO_TEST = { G, startLevel, update, render, distMap, monSees, losClear, get grid() { return grid; }, get MW() { return MW; }, get MH() { return MH; }, kb };
})();
